import '../models/candle.dart';import '../models/direction_result.dart';import 'indicators.dart';class DirectionEngine{DirectionResult analyze(List<Candle> a,{List<Candle>? higher}){final c=a.map((x)=>x.close).toList(),p=c.last,e9=I.ema(c,9),e21=I.ema(c,21),r=I.rsi(c),vw=I.vwap(a),b=I.bb(c);var s=50;final why=<String>[];if(e9>e21){s+=15;why.add('EMA9 > EMA21');}else{s-=15;why.add('EMA9 < EMA21');}if(p>vw){s+=10;why.add('Fiyat VWAP üzerinde');}else{s-=10;why.add('Fiyat VWAP altında');}if(r>=50&&r<=70){s+=8;why.add('RSI momentum destekliyor');}else if(r<40){s-=8;why.add('RSI zayıf');}else if(r>75){s-=5;why.add('Aşırı alım riski');}if(p>b[1]){s-=3;why.add('Üst Bollinger riski');}if(p<b[2]){s+=3;why.add('Alt Bollinger tepki alanı');}if(higher!=null&&higher!.length>25){final h=higher!.map((x)=>x.close).toList();if(I.ema(h,9)>I.ema(h,21)){s+=10;why.add('Üst zaman dilimi yükseliş');}else{s-=10;why.add('Üst zaman dilimi düşüş');}}s=s.clamp(0,100);final d=s>=70?'CALL':s<=30?'PUT':'BEKLE';final conf=d=='CALL'?s:d=='PUT'?100-s:50-(s-50).abs();return DirectionResult(direction:d,score:s,confidence:conf,lastPrice:p,reasons:why,metrics:{'RSI':r,'EMA9':e9,'EMA21':e21,'VWAP':vw,'BB_UP':b[1],'BB_LOW':b[2]});}}
